mapper.delete:
DELETE FROM sys_event_inbox
WHERE service_name = #{serviceName}
  AND create_time < #{createTimeBefore}
LIMIT #{limit}

DELETE FROM sys_event_inbox
WHERE ctid IN (SELECT ctid FROM sys_event_inbox
               WHERE service_name = #{serviceName}
                 AND create_time < #{createTimeBefore}
               LIMIT #{limit})

mapper.select:
SELECT MIN(create_time)
FROM sys_event_inbox
WHERE service_name = #{serviceName}
